issue:
Successive Branches Retain Commits from Previous Iterations

### Bug Description

After cloning a repository into memory (go-billy memfs), procedurally creating and checking out a new local branch, committing changes to the working tree, and repeating this workflow multiple times against a predetermined HEAD hash - each successive iteration includes all commits and changes from prior iterations.

Each branch created against the same hash reference should be isolated, excluding any changes made in a prior iteration. Instead, even when the hash reference explicitly points to a commit prior to these changes, they are still carried forward into each subsequent branch.

### go-git Version

v6.0.0-alpha.1

### Steps to Reproduce

1. Clone a repository using go-billy memfs.
2. Record the HEAD hash of the default branch before making any changes.
3. Create a new local branch based on the recorded hash.
4. Add a file to the working tree, stage it to the index, and create a commit.
5. Repeat steps 3–4 and observe that all files staged in prior iterations are included in each successive branch.

Code Example:
```golang
type client struct {
  repo *git.Repository
  hash plumbing.Hash
}

func NewClient() (*client, error) {
  store := memory.NewStorage()
  fs := memfs.New()
  repo, _ := git.Clone(store, fs, &git.CloneOptions{
    SingleBranch: false,
    URL: url,
  })
  head, _ := repo.Head()
  return &client{
    repo: repo,
    hash: head.Hash(),
  }, nil
}

func (c *client) Do(branch, file, content, msg string) {
  name := plumbing.NewBranchReferenceName(branch)
  ref := plumbing.NewHashReference(name, c.hash)
  c.repo.Storer.SetReference(ref)
  wt, _ := c.repo.Worktree()
  wt.Checkout(&git.CheckoutOptions{
    Branch: name,
    Force: true,
  })
  fileRef, _ := wt.Filesystem.Create(file)
  fileRef.Write([]byte(content))
  fileRef.Close()
  wt.Add(file)
  wt.Commit(msg, &git.CommitOptions{
    Author: &object.Signature{
      Name: "Nick",
      Email: "nick@test.com",
      When: time.Now(),
    },
  })
}

func (c *client) Files() []string {
  wt, _ := c.repo.Worktree()
  var files []string
  util.Walk(wt.Filesystem, ".", func(path string, info os.FileInfo, err error) error {
    files = append(files, path)
    return nil
  })
  return files
}

func Test(t *testing.T) {
  var branches = map[string]struct {
    file string
    content string
    msg string
  }{
    "branch1": {
      file: "test1.txt",
      content: "test1.txt",
      msg: "commit1",
    },
    "branch2": {
      file: "test2.txt",
      content: "test2.txt",
      msg: "commit2",
    },
    "branch3": {
      file: "test3.txt",
      content: "test3.txt",
      msg: "commit3",
    },
  }

  client, _ := NewClient()
  for branch, data := range branches {
    t.Run(branch, func(t *testing.T) {
      client.Do(branch, data.file, data.content, data.msg)
      t.Logf("%s Files: %v", branch, client.Files())
    })
  }
}
```

